def next_smallest_palindrome(num: int) -> int:
    """
    Returns the smallest palindrome strictly greater than num.
    """

    def is_all_nines(s: str) -> bool:
        return all(ch == '9' for ch in s)

    def make_palindrome(left: str, odd_length: bool) -> int:
        # Mirror left to form palindrome
        if odd_length:
            pal_str = left + left[:-1][::-1]
        else:
            pal_str = left + left[::-1]
        return int(pal_str)

    s = str(num)
    length = len(s)

    # If all 9's, next palindrome is 10..01 e.g. 999 -> 1001
    if is_all_nines(s):
        return num + 2  # e.g., 9->11, 99->101, 999->1001

    odd_length = (length % 2 != 0)
    mid = length // 2

    if odd_length:
        left = s[:mid+1]
    else:
        left = s[:mid]

    # Form palindrome by mirroring left to right
    pal = make_palindrome(left, odd_length)

    # If palindrome is strictly greater than num, return it
    if pal > num:
        return pal

    # Otherwise increment the left part and then form palindrome again
    if odd_length:
        # Increment left string as number
        incremented = str(int(left) + 1)
        # If incrementing left changes length (e.g. 999 -> 1000)
        if len(incremented) > len(left):
            # Length has increased, so palindrome length increases by 1
            # e.g. 999 -> 1001
            return int('1' + ('0' * (length -1)) + '1')
        else:
            return make_palindrome(incremented, odd_length)
    else:
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):
            # e.g. 99 -> 101
            return int('1' + ('0' * (length -1)) + '1')
        else:
            return make_palindrome(incremented, odd_length)

