from collections.abc import Iterable, Mapping

def remove_column(data, pos):
    """
    Remove the element at index `pos` from each inner grouping within a multi-level collection,
    preserving the outer collection's type exactly if possible (including sets or dicts).

    Args:
        data: A multi-level collection.
        pos: Position index to remove from each inner grouping.

    Returns:
        A collection like `data` but with the element at `pos` removed from each inner grouping.
    """

    def is_inner_grouping(x):
        # Inner grouping is any iterable but NOT a string or mapping
        return (
            isinstance(x, Iterable)
            and not isinstance(x, (str, Mapping))
        )

    def remove_from_inner(group):
        # Remove element at pos from inner group, preserving type if possible
        if isinstance(group, Mapping):
            # For mappings, remove the item at position pos in the list of keys sorted by insertion order
            # But the problem states "position from each inner grouping", so treat mappings as collections of pairs?
            # User answer says preserve outer type if possible, but inner grouping—should we handle mappings here?
            # The problem examples do not clarify mappings inside inner grouping.
            # We'll treat mappings as not inner grouping to remove from.
            return group

        if not is_inner_grouping(group):
            return group

        # Convert group to list to remove by index
        try:
            seq = list(group)
        except TypeError:
            return group  # not subscriptable or iterable

        if pos < 0 or pos >= len(seq):
            # position out of range: return group unchanged but preserving type
            return group

        # Remove element at pos
        del seq[pos]

        # Restore type if possible
        t = type(group)
        try:
            if issubclass(t, tuple):
                return t(seq)
            elif issubclass(t, list):
                return seq
            elif issubclass(t, set):
                return t(seq)
            else:
                # For other iterables, try to reconstruct
                return t(seq)
        except Exception:
            # fallback to list
            return seq

    # Now recursively process data

    if isinstance(data, Mapping):
        # For mappings, preserve type and process values recursively
        t = type(data)
        # For dict-like, preserve keys and apply remove_column on values
        new_items = ((k, remove_column(v, pos)) for k, v in data.items())
        try:
            return t(new_items)
        except Exception:
            # fallback to dict
            return dict(new_items)

    if is_inner_grouping(data):
        # data is inner grouping: remove element at pos
        return remove_from_inner(data)

    # For outer collection that is iterable but not mapping or inner grouping (e.g., list of inner groupings)
    if isinstance(data, Iterable) and not isinstance(data, (str, bytes)):
        t = type(data)
        try:
            # Recursively apply on each element
            new_data = [remove_column(el, pos) for el in data]
            if issubclass(t, tuple):
                return t(new_data)
            elif issubclass(t, list):
                return new_data
            elif issubclass(t, set):
                return t(new_data)
            else:
                # Try to reconstruct
                return t(new_data)
        except Exception:
            # fallback to list
            return [remove_column(el, pos) for el in data]

    # For non-iterables or strings, return as is
    return data

