def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # If all digits are 9, the next palindrome is 10...01 (length+1)
    if all(ch == '9' for ch in s):
        return n + 2  # e.g. 9 -> 11, 99 -> 101, 999 -> 1001

    # Helper to check if palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Construct a palindrome by copying the left side to right
    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    # Increment the middle part of the palindrome
    def increment_mid(left: str, odd_length: bool) -> str:
        if odd_length:
            # increment the middle digit
            left_list = list(left)
            i = len(left_list) - 1
            while i >= 0:
                if left_list[i] != '9':
                    left_list[i] = str(int(left_list[i]) + 1)
                    break
                else:
                    left_list[i] = '0'
                    i -= 1
            else:
                # overflow, e.g. 999 -> 1000
                left_list.insert(0, '1')
            return ''.join(left_list)
        else:
            # increment the left half
            left_num = int(left)
            left_num += 1
            return str(left_num)

    odd_length = (length % 2 != 0)
    mid = (length + 1) // 2
    left = s[:mid]

    # Generate palindrome by mirroring left side
    palindrome = make_palindrome(left, odd_length)

    if int(palindrome) > n:
        return int(palindrome)
    else:
        # Need to increment left part and form palindrome again
        new_left = increment_mid(left, odd_length)

        # Handle overflow in length (e.g. 999 -> 1000)
        if len(new_left) > len(left):
            # This means length increased by 1, palindrome length also increases by 1 or 2
            # The next palindrome is 10...01 with length+1
            return int('1' + ('0' * (length - 1)) + '1')

        palindrome = make_palindrome(new_left, odd_length)
