def get_total_number_of_sequences(elements, length):
    elements = sorted(elements)
    n = len(elements)
    memo = {}

    def dfs(prev_index, remaining):
        if remaining == 0:
            return 1
        key = (prev_index, remaining)
        if key in memo:
            return memo[key]
        total = 0
        prev_val = elements[prev_index] if prev_index != -1 else None
        start = 0 if prev_index == -1 else prev_index + 1
        for i in range(start, n):
            val = elements[i]
            if prev_val is None or val >= 2 * prev_val:
                total += dfs(i, remaining - 1)
        memo[key] = total
        return total

    return dfs(-1, length)

