def next_smallest_palindrome(num: int) -> int:
    """
    Return the smallest palindrome strictly greater than the given number.
    """

    def is_all_nines(n_str):
        return all(ch == '9' for ch in n_str)

    s = str(num)
    length = len(s)

    # If all digits are 9, the next palindrome is 10...01 with length+1 digits
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to create palindrome by mirroring left to right
    def make_palindrome(left, middle, odd_length):
        if odd_length:
            return left + middle + left[::-1]
        else:
            return left + left[::-1]

    odd_length = (length % 2 != 0)
    mid_index = length // 2

    if odd_length:
        left = s[:mid_index]
        middle = s[mid_index]
        right = s[mid_index+1:]
    else:
        left = s[:mid_index]
        middle = ''
        right = s[mid_index:]

    # Construct palindrome by mirroring left + middle to right
    palindrome = make_palindrome(left, middle, odd_length)
    palindrome_num = int(palindrome)

    if palindrome_num > num:
        return palindrome_num

    # If palindrome_num <= num, increment the middle part and mirror again
    if odd_length:
        # Increment the middle digit + left part as a single number
        left_middle_num = int(left + middle)
        left_middle_num += 1
        left_middle_str = str(left_middle_num)

        # If length changed after increment (e.g. 999 -> 1000), adjust accordingly
        if len(left_middle_str) > len(left + middle):
            # This means the palindrome length increases by 1 digit
            # e.g. 999 -> 1001
            return int('1' + ('0' * (length - 1)) + '1')

        new_left = left_middle_str[:-1]
        new_middle = left_middle_str[-1]
        palindrome = make_palindrome(new_left, new_middle, True)
        return int(palindrome)

    else:
        # even length: increment left part as a whole number
        left_num = int(left)
        left_num += 1
        left_str = str(left_num)

        if len(left_str) > len(left):
            # length increased, e.g. 99 -> 100, palindrome length increases by 1
            return int('1' + ('0' * (length - 1)) + '1')

        palindrome = make_palindrome(left_str, '', False)
        return int(palindrome)

