    """
    Returns the smallest palindrome strictly greater than the given number.
    """
    def is_all_nines(n_str):
        return all(ch == '9' for ch in n_str)

    s = str(num)
    length = len(s)

    # If all 9's, the next palindrome is 10..01 with length+1 digits
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Convert to list of digits for easy manipulation
    digits = list(map(int, s))

    # Helper to build palindrome by mirroring left to right
    def make_palindrome(left, length):
        if length % 2 == 0:
            return left + left[::-1]
        else:
            return left + left[-2::-1]

    # Split number into left half and middle (if odd length)
    half_len = (length + 1) // 2
    left_half = digits[:half_len]

    # Form a palindrome by mirroring left_half
    pal_candidate_digits = left_half[:]
    if length % 2 == 0:
        pal_candidate_digits += left_half[::-1]
    else:
        pal_candidate_digits += left_half[-2::-1]

    pal_candidate = int(''.join(map(str, pal_candidate_digits)))

    # If palindrome candidate is strictly greater than num, return it
    if pal_candidate > num:
        return pal_candidate

    # Otherwise, increment the left half and form palindrome again
    # Increment left_half as a number
    left_num = int(''.join(map(str, left_half)))
    left_num += 1
    left_half_str = str(left_num)

    # If increment caused length change (like 999 -> 1000)
    if len(left_half_str) > len(left_half):
        # For example, 999 + 1 = 1000, length increased by 1
        # This means something like 999 -> next palindrome is 1000001 for length=6
        # So build palindrome accordingly with new left_half_str
        if length % 2 == 0:
            # even length, new palindrome length increases by 1
            new_pal = left_half_str + left_half_str[:-1][::-1]
        else:
            # odd length, new palindrome length increases by 1
            new_pal = left_half_str + left_half_str[:-2][::-1]
        return int(new_pal)

    # Otherwise build palindrome with incremented left_half
    if length % 2 == 0:
        new_pal_candidate = left_half_str + left_half_str[::-1]
    else:
        new_pal_candidate = left_half_str + left_half_str[-2::-1]

