def monotonic(l):
    # Helper function to check duplicates recursively
    def has_duplicates(seq, seen=frozenset()):
        if not seq:
            return False
        if seq[0] in seen:
            return True
        return has_duplicates(seq[1:], seen | {seq[0]})

    # Helper function to check strictly increasing recursively
    def strictly_increasing(seq):
        if len(seq) < 2:
            return True
        return seq[0] < seq[1] and strictly_increasing(seq[1:])

    # Helper function to check strictly decreasing recursively
    def strictly_decreasing(seq):
        if len(seq) < 2:
            return True
        return seq[0] > seq[1] and strictly_decreasing(seq[1:])

    # Helper function to sum list recursively
    def recursive_sum(seq):
        if not seq:
            return 0
        return seq[0] + recursive_sum(seq[1:])

    # Helper function to concatenate string recursively
    def recursive_concat(seq):
        if not seq:
            return ""
        return seq[0] + recursive_concat(seq[1:])

    # Check if input is list or str
    if isinstance(l, list):
        # For list: return single bool
        if has_duplicates(l):
            return False
        return strictly_increasing(l) or strictly_decreasing(l)
    elif isinstance(l, str):
        # For string: always return tuple (bool, string)
        if has_duplicates(l):
            return False, l
        inc = strictly_increasing(l)
        dec = strictly_decreasing(l)
        return (inc or dec), l
    else:
        raise TypeError("Input must be a list or a string")

